class Solution {
  public long maxTotalValue(int[] nums, int k) {
    int n = nums.length;
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    int[][] mx = new int[LOG][], mn = new int[LOG][];
    mx[0] = nums.clone();
    mn[0] = nums.clone();
    for (int j = 1; j < LOG; j++) {
      mx[j] = new int[n];
      mn[j] = new int[n];
      for (int i = 0; i + (1 << j) <= n; i++) {
        mx[j][i] = Math.max(mx[j - 1][i], mx[j - 1][i + (1 << (j - 1))]);
        mn[j][i] = Math.min(mn[j - 1][i], mn[j - 1][i + (1 << (j - 1))]);
      }
    }
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(b[0], a[0]));
    for (int l = 0; l < n; l++) pq.add(new long[] {value(mx, mn, l, n - 1), l, n - 1});
    long total = 0;
    for (int t = 0; t < k; t++) {
      long[] top = pq.poll();
      total += top[0];
      int l = (int) top[1], r = (int) top[2];
      if (r - 1 >= l) pq.add(new long[] {value(mx, mn, l, r - 1), l, r - 1});
    }
    return total;
  }

  private static long value(int[][] mx, int[][] mn, int l, int r) {
    int j = 31 - Integer.numberOfLeadingZeros(r - l + 1);
    return Math.max(mx[j][l], mx[j][r - (1 << j) + 1])
        - Math.min(mn[j][l], mn[j][r - (1 << j) + 1]);
  }
}
